-- Resources content for Campaigns and Events (CLAUDE.md, "Resources stay in step with the code"). Content only; no schema.
-- The prefix continues the sequence past 20261111120000; see 20261103120000's header on why a prefix is a sequence number.
--
-- What changed for a reader: Audience Listening gained Campaigns and Events beside Queries (phase D, first half), a Coordinator role
-- that approves public events for listing, tables with single-use links, and printable table cards. The guide is new rather than an
-- edit of an existing one so an editor's changes to those are not touched.
--
-- Station-neutral on purpose: a guide is kept data, and the fresh-install check fails on any kept guide that names a station.

select private.rc_release_guide(
  p_slug => 'audience-listening-campaigns-events-and-table-cards',
  p_tool_key => 'audience-listening',
  p_title => 'Campaigns, events and table cards',
  p_summary => 'Set up a season of listening, schedule events inside it, get a public event listed, and print the cards for its tables.',
  p_screen_keys => array['audience-listening.campaigns', 'audience-listening.campaign', 'audience-listening.events', 'audience-listening.event'],
  p_sort_order => 50,
  p_version_note => 'Campaigns, Events and table cards',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"campaign","marks":[{"type":"bold"}]},{"type":"text","text":" is a season of listening: one question, the prompts a table is walked through, a list of tags, and the dates it runs. An "},{"type":"text","text":"event","marks":[{"type":"bold"}]},{"type":"text","text":" is a session in a place at a time inside that season, and a "},{"type":"text","text":"table","marks":[{"type":"bold"}]},{"type":"text","text":" is one conversation at it. A kitchen table is an event with one table. Campaigns and Events sit beside Queries in the section's navigation."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Campaigns"}]},{"type":"paragraph","content":[{"type":"text","text":"Choose Campaigns, then New campaign. Give it a title, the question it asks, an introduction for the website, and the dates it opens and closes. It starts as a draft and nothing is public."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Prompts and tags","marks":[{"type":"bold"}]},{"type":"text","text":" holds what a table is asked, in order, and the words a facilitator picks from when they mark a line as what mattered. Each prompt can carry a hint for the facilitator and a suggested time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open the campaign once it has at least one prompt. Closing it also closes the query linked to it under Settings, so a question is not still taking answers after the season is over."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only a draft with no events can be deleted. A campaign that ran is closed and then archived, so what it heard stays on the record."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Events"}]},{"type":"paragraph","content":[{"type":"text","text":"Add an event from its campaign's Events tab. Its start has to fall inside the campaign's dates; the Portal refuses it otherwise. Times are the station's local time."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"private","marks":[{"type":"bold"}]},{"type":"text","text":" event is never listed. The organizer shares it themselves."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"public","marks":[{"type":"bold"}]},{"type":"text","text":" event needs an address and a number of seats, and can be listed on the website only after a coordinator approves it. Anyone can ask for a review. A coordinator approves it after ticking each item on the checklist (a public place, an identified organizer with a verified email, a date inside the campaign, accessibility details, not a fundraiser or campaign event, and the consent reading acknowledged), or declines it with a reason the organizer is told."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If anyone other than a coordinator changes what the public sees on a listed event (its title, time, place, address or seats), it goes back to review. Making an event private takes it off the website at once."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Approving, declining and taking an event off the website are recorded with who did them. The Events page can show only those waiting for review, and the count appears beside Events in the navigation."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Tables and cards"}]},{"type":"paragraph","content":[{"type":"text","text":"On an event, add the tables it needs. "},{"type":"text","text":"Make new links and cards for every table","marks":[{"type":"bold"}]},{"type":"text","text":" gives each table a single-use link and draws a card for it with a QR code, to print at 7 by 5 inches, one to a page."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A link is shown once, on that page. The Portal keeps only a scrambled copy, so a card cannot be reprinted later. To get a card back, make a new link."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A new link replaces the old one. A card printed earlier, and any phone using it, stops working. If one phone is lost or cannot scan, make a new link for that table alone and read it out or show it to the person."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Making links needs the website's address to be set on the server. If it is not, the page says so instead of printing a card that goes nowhere."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A table that has not started can be removed. One that has been agreed to or recorded is kept."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Seats"}]},{"type":"paragraph","content":[{"type":"text","text":"A public event shows the seats people have saved, each with a name and an email given for that event only. Remove one to free the seat and delete the details."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Recording at a table, the group agreement, the room console and the conversation review come next. Until the website page that a card opens is in place, a printed card does not open anything, so do not print cards for a real session yet."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nothing on these pages is public until you say so, and a public event is never listed without a coordinator."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-11-11-audience-listening-campaigns-events',
  p_tool_key => 'audience-listening',
  p_released_on => '2026-11-11',
  p_title => 'Campaigns, events and table cards arrive in Audience Listening',
  p_guide_slugs => array['audience-listening-campaigns-events-and-table-cards'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Audience Listening has two new pages, Campaigns and Events, beside Queries. A campaign holds a season's question, its prompts, its tags and its dates, and closing it closes its linked query. Events belong to a campaign and start inside its dates. A public event is listed on the website only after a coordinator approves it, and a new Coordinator role can be granted to name who does that. Each event has tables, and a table gets a single-use link and a printable card with a QR code; the link is shown once and a new one replaces the old. Saved seats are listed on the event. Recording at a table, the group agreement and the room console are not here yet, so the cards are not ready for a real session."}]}]}$body$
);
